def comps(vals, rmax, cmax):
    seen=set(); out=[]
    for r in range(rmax):
      for c in range(cmax):
        if grid[r][c] not in vals or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        for a,b in q:
          cells.append((a,b))
          for p in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            x,y=p
            if 0<=x<rmax and 0<=y<cmax and grid[x][y] in vals and p not in seen:
              seen.add(p);q.append(p)
        out.append(cells)
    return out
